package com.example.smartexpenseanalyzer.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.servlet.HandlerInterceptor; import java.io.IOException;
@Component public class SessionGuard implements HandlerInterceptor { public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler)throws IOException { String path=req.getRequestURI(); if(!path.startsWith("/api/")) return true; if(path.equals("/api/auth/login")||path.equals("/api/auth/register")||path.equals("/api/auth/logout")) return true; HttpSession s=req.getSession(false); if(s==null||s.getAttribute("uid")==null){res.sendError(401,"Please sign in");return false;} if(path.startsWith("/api/admin/")&&!"ADMIN".equals(s.getAttribute("role"))){res.sendError(403,"Administrator access required");return false;} return true; } }
